/* ============================================================
   HOW WORKS STEPS (navy section) — how-works-steps.module.css
   Mirrors the existing how-it-works.module.css patterns
   ============================================================ */

.section {
  -webkit-text-fill-color: inherit;
  background-color: var(--color-text-primary);
  background-clip: border-box;
  margin-bottom: 0;
  padding: 70px 5% 80px;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 0;
}

.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 0;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 500;
  color: var(--color-brand-cyan);
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
}

/* Heading */
.heading {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  text-align: center;
  line-height: 48px;
  margin-top: 0;
  margin-bottom: 20px;
}

/* Subtitle */
.subtitle {
  color: #fff;
  opacity: 0.8;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
}

/* Feature cards grid */
.featureGrid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  margin-top: 40px;
}

.featureCard {
  grid-column-gap: 0;
  grid-row-gap: 0;
  text-align: center;
  background-color: var(--color-text-primary);
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 20px;
  flex-flow: column;
  justify-content: space-between;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.textWrapper {
  margin-bottom: 20px;
}

.cardTitle {
  color: #fff;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

.cardDesc {
  color: #fff;
  opacity: 0.8;
  min-height: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  letter-spacing: -0.08px;
  margin-bottom: 20px;
  line-height: 28px;
}

.fullWidthImage {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .featureCard {
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .featureCard {
    padding-left: 25px;
    padding-right: 25px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .heading {
    font-size: 35px;
    line-height: 45px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding: 50px 5% 60px;
    margin-top: 0;
  }

  .featureGrid {
    grid-template-columns: 1fr;
    margin-top: 20px;
  }

  .featureCard {
    padding-left: 18px;
    padding-right: 18px;
  }

  .cardTitle {
    text-align: center;
  }

  .cardDesc {
    text-align: center;
  }

  .heading {
    font-size: 30px;
    line-height: 32px;
    margin-bottom: 10px;
    text-align: center;
  }

  .subtitle {
    text-align: center;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding: 50px 5% 60px;
    margin-top: 0;
  }

  .featureGrid {
    grid-template-columns: 1fr;
  }
}

import Image from "next/image";
import { Button } from '@/components/primitives/button';
import styles from "./how-works-hero.module.css";

const STAT_BADGES = [
  {
    icon: "/images/webflow/Layer_1-3.svg",
    label: "White-Label by Default",
  },
  {
    icon: "/images/webflow/Layer_1-25.svg",
    label: "Senior-Level Team",
  },
  {
    icon: "/images/webflow/Layer_1-22.svg",
    label: "No Long-Term Contract",
  },
  {
    icon: "/images/webflow/Layer_1-26.svg",
    label: "Pause or Scale Anytime",
  },
];

export function HowWorksHero() {
  return (
    <div className={styles["section"]}>
      <div className={styles["container"]}>
        <div className={styles["inner"]}>
          {/* Badge */}
          <div className={styles["badgeRow"]}>
            <div className={styles["badge"]}>
              <p className={styles["badgeText"]}>Boldteq Work</p>
            </div>
          </div>

          {/* Heading */}
          <h1 className={styles["heading"]}>How Boldteq Works</h1>

          {/* Subtitle */}
          <p className={styles["subtitle"]}>
            A simple, structured white-label delivery process built for agency
            workflows from request to client-ready delivery.
          </p>

          {/* Stat badges grid */}
          <div className={styles["badgeGridWrap"]}>
            <div className={styles["badgeGrid"]}>
              {STAT_BADGES.map((badge) => (
                <div key={badge.label} className={styles["statBadge"]}>
                  <Image
                    src={badge.icon}
                    alt={`${badge.label} icon`}
                    width={24}
                    height={24}
                    loading="eager"
                  />
                  <p className={styles["statBadgeText"]}>{badge.label}</p>
                </div>
              ))}
            </div>
          </div>

          {/* GuideJar video embed */}
          <div className={styles["videoWrap"]}>
            <div className={styles["videoContainer"]}>
              <iframe
                src="https://www.guidejar.com/embed/xvH9rRaAyggwH1eetyrl?type=1&controls=on"
                width="100%"
                height="100%"
                style={{ position: "absolute", inset: 0 }}
                allowFullScreen
                title="How Boldteq white-label delivery works"
              />
            </div>
          </div>

          {/* CTA buttons */}
          <div className={styles["ctaRow"]}>
            <Button href="/pricing" variant="primary" size="md">
              See Plans
            </Button>
            <Button href="/book-a-demo" variant="secondary" size="md">
              Book a Demo
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

