/* ============================================================
   HOW WORKS HERO — how-works-hero.module.css
   Matches: .how-works-banner on how-it-works.html
   ============================================================ */

.section {
  background-color: #0000;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  justify-content: center;
  align-items: center;
  display: flex;
  margin-bottom: 1rem;
}

.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
  margin-bottom: 17px;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 700;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  padding-top: 6px;
  padding-bottom: 6px;
}

/* Heading (.web-ban-title.mob-margin-less) */
.heading {
  color: var(--color-brand-navy);
  margin-top: 1.5rem;
  margin-bottom: 10px;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 50px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* Subtitle (.h1-season-seeing.web-h1) */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* Stat badges (.web-job-attention + .web-ban-grid.mob-2grid) */
.badgeGridWrap {
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
}

.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* Individual badge box (.web-grid-box) */
.statBadge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.statBadgeText {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* Video embed (.code-embed-3.how-code-embed.margin-top-50) */
.videoWrap {
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  margin: 50px auto 40px;
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.videoContainer {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  padding-bottom: calc(56.25% + 32px);
  border-radius: 10px;
}

/* CTA buttons */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  gap: 0;
  flex-wrap: wrap;
}

/* Primary: .a-gulf-book */
.btnPrimary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: var(--shadow-card);
}

.btnPrimary:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* Secondary: .navy-arrow-btn */
.btnSecondary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-color: var(--color-text-primary);
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-left: 1.25rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
}

.btnSecondary:hover {
  color: var(--color-brand-blue);
  background-color: var(--color-accent-bg-hover);
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .heading {
    font-size: 3.75rem;
    line-height: 1.25;
  }

  .badgeGrid {
    max-width: 1000px;
  }

  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .heading {
    font-size: 3.75rem;
    line-height: 1.25;
  }

  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .heading {
    font-size: 2.5rem;
    line-height: 1.25;
    margin-bottom: 10px;
  }

  .videoWrap {
    margin-top: 20px;
    margin-bottom: 20px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 1.9rem;
    line-height: 1.25;
  }

  .badgeGridWrap {
    justify-content: center;
    align-items: center;
    display: flex;
  }

  .badgeGrid {
    grid-column-gap: 15px;
    grid-row-gap: 15px;
    grid-template-rows: auto;
    grid-template-columns: 1fr 1fr;
    grid-auto-columns: 1fr;
    display: grid;
    width: 100%;
  }

  .statBadge {
    width: 100%;
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 3rem;
    padding-bottom: 2rem;
  }

  .container {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .heading {
    font-size: 1.6rem;
    line-height: 1.25;
  }

  .subtitle {
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGridWrap {
    flex-direction: column;
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGrid {
    grid-column-gap: 10px;
    grid-row-gap: 10px;
    max-width: 100%;
    margin-bottom: 0;
  }

  .statBadge {
    flex-flow: column;
    width: 100%;
    align-items: center;
    padding: 10px;
  }

  .statBadgeText {
    text-align: center;
    font-size: 1rem;
    line-height: 16px;
  }

  .ctaRow {
    flex-direction: column;
    gap: 0.75rem;
  }

  .btnPrimary,
  .btnSecondary {
    background-color: var(--color-brand-blue);
    background-size: 29px 29px;
    flex-direction: column;
    width: 100%;
    margin-left: 0;
    font-size: 1.1rem;
  }
}

import Image from "next/image";
import styles from "./risk-removal.module.css";

const CARDS = [
  {
    icon: "/images/webflow/Layer_1-30.svg",
    title: "White-Label by Default",
    text: "Every deliverable is produced under your brand. We remain fully invisible and never communicate with your clients \u2014 your agency stays front and center.",
  },
  {
    icon: "/images/webflow/Layer_1-20.svg",
    title: "Dedicated Team",
    text: "You work with a consistent delivery team that understands your workflow, standards, and expectations \u2014 not rotating or anonymous freelancers.",
  },
  {
    icon: "/images/webflow/Layer_1-10.svg",
    title: "Predictable Turnaround",
    text: "Clear turnaround timelines are defined based on task scope and your selected plan, so you always know what\u2019s coming and when.",
  },
  {
    icon: "/images/webflow/Layer_1-32.svg",
    title: "Quality Control",
    text: "Each task goes through internal quality checks to ensure accuracy, consistency, and client-ready output before delivery.",
  },
];

export function RiskRemoval() {
  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <div className={styles.header}>
          <h2 className={styles.heading}>
            Designed to Remove Risk at Every Step
          </h2>
          <p className={styles.subtitle}>
            From white-label delivery to quality checks and dedicated teams,
            every safeguard exists to protect your client relationships and
            reputation.
          </p>
        </div>

        <div className={styles.grid}>
          {CARDS.map((card) => (
            <div key={card.title} className={styles.card}>
              <Image
                src={card.icon}
                alt={`${card.title} icon`}
                width={40}
                height={40}
                className={styles.cardIcon}
              />
              <h3 className={styles.cardTitle}>{card.title}</h3>
              <p className={styles.cardText}>{card.text}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

