  margin-bottom: 7px;
  text-align: left;
}

.cardText {
  color: var(--color-text-secondary);
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .section {
    padding-bottom: 70px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section {
    padding-bottom: 70px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding-bottom: 60px;
    padding-left: 2%;
    padding-right: 2%;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding-bottom: 60px;
  }

  .grid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 0;
    padding-bottom: 60px;
  }

  .heading {
    font-size: 1.5rem;
    line-height: 1.3;
  }

  .subtitle {
    font-size: 0.9375rem;
  }

  .grid {
    grid-template-columns: 1fr;
  }
}

import Image from "next/image";
import styles from "./how-works-steps.module.css";

const STEPS = [
  {
    title: "Choose Your Subscription",
    description:
