@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  /* RoobertPRO font */
  --font-roobert: var(--font-roobert);
  --font-sans: var(--font-roobert);
  --font-mono: var(--font-roobert);
  --font-heading: var(--font-roobert);

  /* Boldteq Brand Colors */
  --color-brand-navy: #092245;
  --color-brand-navy-deep: #082753;
  --color-brand-cyan: #21cfff;
  --color-brand-blue: #019ae6;
  --color-brand-yellow: #FFEB85;
  --color-brand-dark: #111827;
  --color-brand-dark-alt: #1a1925;
  --color-brand-green: #3c7c43;
  --color-brand-green-badge: #18c958;
  --color-brand-light-blue: #ecf7fd;
  --color-brand-light-bg: #f5f7fa;
  --color-brand-gray-bg: #f7f7f8;
  --color-brand-card-hover: #cdebfa;
  --color-brand-card-border: #009ce0;

  /* shadcn semantic tokens */
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* ─── Z-index design tokens ─────────────────────────────────────────────────── */
:root {
  --z-toast: 10000;
  --z-modal: 9999999;
  --z-nav: 999999;
  --z-overlay: 50;
  --z-sticky: 30;
  --z-base: 1;
}

/* ─── Spacing scale (4px base) ──────────────────────────────────────────────── */
:root {
  --space-0: 0;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 28px;
  --space-8: 32px;
  --space-9: 36px;
  --space-10: 40px;
  --space-12: 48px;
  --space-14: 56px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;
  --space-28: 112px;
  --space-32: 128px;
}

/* ─── Typography scale (Webflow-derived) ────────────────────────────────────── */
:root {
  --text-xs: 12px;
  --text-sm: 14px;
  --text-base: 16px;
  --text-md: 18px;
  --text-lg: 20px;
  --text-xl: 24px;
  --text-2xl: 32px;
  --text-3xl: 40px;
  --text-4xl: 50px;

  --leading-tight: 1.2;
  --leading-snug: 1.3;
  --leading-normal: 1.5;
  --leading-relaxed: 1.75;

  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
}

/* ─── Shadow scale ──────────────────────────────────────────────────────────── */
:root {
  --shadow-card: 0 0 5px rgba(0, 0, 0, 0.1);
  --shadow-card-hover: 0 4px 16px -4px rgba(0, 0, 0, 0.1);
  --shadow-card-soft: 0 0 80px rgba(175, 175, 175, 0.1);
  --shadow-card-cyan: 0 4px 20px rgba(1, 154, 230, 0.1);
  --shadow-popover:
    0 109.603px 30.372px rgba(0, 0, 0, 0),
    0 69.987px 27.731px rgba(0, 0, 0, 0.012),
    0 39.615px 23.769px rgba(0, 0, 0, 0.04),
    0 17.167px 17.167px rgba(0, 0, 0, 0.071),
    0 3.962px 9.244px rgba(0, 0, 0, 0.082);
  --shadow-glow: 0 0 50px rgba(0, 0, 0, 0.2);
  --shadow-pricing: 0 0 80px rgba(0, 0, 0, 0.1);
  --shadow-button: 0 0 5px rgba(0, 0, 0, 0.1);
  --shadow-focus-ring: 0 0 0 3px rgba(33, 207, 255, 0.15);
  --shadow-pop-deep: 0 24px 80px rgba(0, 0, 0, 0.25);
}

/* ─── Border radius scale ───────────────────────────────────────────────────── */
:root {
  --radius-xs: 4px;
  --radius-s: 6px;
  --radius-m: 8px;
  --radius-l: 10px;
  --radius-xl: 12px;
  --radius-2xl: 15px;
  --radius-3xl: 20px;
  --radius-pill: 999px;
}

/* ─── Motion tokens ─────────────────────────────────────────────────────────── */
:root {
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;
  --duration-slower: 600ms;
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-decelerate: cubic-bezier(0, 0, 0.2, 1);
  --ease-accelerate: cubic-bezier(0.4, 0, 1, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ─── Semantic color aliases (used by primitives) ───────────────────────────── */
:root {
  --color-text-primary: #082753;
  --color-text-secondary: #2b2b2b;
  --color-text-muted: #5b616e;
  --color-text-subtle: #6b7280;
  --color-text-on-dark: #ffffff;
  --color-text-on-dark-muted: rgba(255, 255, 255, 0.8);

  --color-surface: #ffffff;
  --color-surface-alt: #f5f7fa;
  --color-surface-muted: #f7f7f8;
  --color-surface-dark: #082753;
  --color-surface-dark-alt: #092245;

  --color-border-subtle: #edeff3;
  --color-border-default: #e5e7eb;
  --color-border-strong: #dde3e8;
  --color-border-cyan: rgba(33, 207, 255, 0.23);

  --color-accent-bg: rgba(33, 207, 255, 0.07);
  --color-accent-bg-hover: rgba(33, 207, 255, 0.12);
  --color-cyan-tint: #effafe;

  --color-success-bg: #def4ff;
  --color-success-fg: #082753;
  --color-info-bg: #e6f7ff;
  --color-info-fg: #0050b3;
  --color-info-border: #91d5ff;
  --color-danger: #ef4444;
  --color-danger-bg: #fff2eb;

