/* ============================================================
   HOW WORKS STEPS (navy section) — how-works-steps.module.css
   Mirrors the existing how-it-works.module.css patterns
   ============================================================ */

.section {
  -webkit-text-fill-color: inherit;
  background-color: var(--color-text-primary);
  background-clip: border-box;
  margin-bottom: 0;
  padding: 70px 5% 80px;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 0;
}

.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 0;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 500;
  color: var(--color-brand-cyan);
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
}

/* Heading */
.heading {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  text-align: center;
  line-height: 48px;
  margin-top: 0;
  margin-bottom: 20px;
}

/* Subtitle */
.subtitle {
  color: #fff;
  opacity: 0.8;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
}

/* Feature cards grid */
.featureGrid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  margin-top: 40px;
}

.featureCard {
  grid-column-gap: 0;
  grid-row-gap: 0;
  text-align: center;
  background-color: var(--color-text-primary);
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 20px;
  flex-flow: column;
  justify-content: space-between;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.textWrapper {
  margin-bottom: 20px;
}

.cardTitle {
  color: #fff;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

.cardDesc {
  color: #fff;
  opacity: 0.8;
  min-height: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  letter-spacing: -0.08px;
  margin-bottom: 20px;
  line-height: 28px;
}

.fullWidthImage {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .featureCard {
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .featureCard {
    padding-left: 25px;
    padding-right: 25px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .heading {
    font-size: 35px;
    line-height: 45px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding: 50px 5% 60px;
    margin-top: 0;
  }

  .featureGrid {
    grid-template-columns: 1fr;
    margin-top: 20px;
  }

  .featureCard {
    padding-left: 18px;
    padding-right: 18px;
  }

  .cardTitle {
    text-align: center;
  }

  .cardDesc {
    text-align: center;
  }

  .heading {
    font-size: 30px;
    line-height: 32px;
    margin-bottom: 10px;
